import{_ as r,a as e,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 17 随：跟随之前先辨其正至19 临：接近众人，也预见盛势的限度","description":"依据《周易》与《周易正义》，逐爻阅读第十七至第二十四卦，讨论相随、整治、观察、刑法、文饰与往复。","frontmatter":{"title":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 17 随：跟随之前先辨其正至19 临：接近众人，也预见盛势的限度","description":"依据《周易》与《周易正义》，逐爻阅读第十七至第二十四卦，讨论相随、整治、观察、刑法、文饰与往复。","splitFrom":"life/personal/yijing/hexagrams-17-24.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读三：随蛊临观至噬嗑贲剥复","summary":"依据《周易》与《周易正义》，逐爻阅读第十七至第二十四卦，讨论相随、整治、观察、刑法、文饰与往复。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读三：随蛊临观至噬嗑贲剥复","link":"/life/personal/yijing/hexagrams-17-24"},"next":{"text":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 20 观：观看他人，也让自己的行为可被检验至22 贲：文饰如何与真实相称","link":"/life/personal/yijing/hexagrams-17-24-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读三：随蛊临观至噬嗑贲剥复","link":"/life/personal/yijing/hexagrams-17-24"},"next":{"text":"六十四卦详读三：随蛊临观至噬嗑贲剥复 · 20 观：观看他人，也让自己的行为可被检验至22 贲：文饰如何与真实相称","link":"/life/personal/yijing/hexagrams-17-24-part-02"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-17-24-part-01.md","filePath":"life/personal/yijing/hexagrams-17-24-part-01.md"}'),o={name:"life/personal/yijing/hexagrams-17-24-part-01.md"};function s(i,t,d,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读三-随蛊临观至噬嗑贲剥复-·-17-随-跟随之前先辨其正至19-临-接近众人-也预见盛势的限度" tabindex="-1">六十四卦详读三：随蛊临观至噬嗑贲剥复 · 17 随：跟随之前先辨其正至19 临：接近众人，也预见盛势的限度 <a class="header-anchor" href="#六十四卦详读三-随蛊临观至噬嗑贲剥复-·-17-随-跟随之前先辨其正至19-临-接近众人-也预见盛势的限度" aria-label="Permalink to &quot;六十四卦详读三：随蛊临观至噬嗑贲剥复 · 17 随：跟随之前先辨其正至19 临：接近众人，也预见盛势的限度&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-17-24">返回分篇目录</a></p><p>本组把注意力从个人进退转向关系如何形成、积弊如何修复、治理如何实施。随与蛊可比较顺从与整治，临与观可比较接近与审视，噬嗑与贲可比较强制裁断与文明表达，剥与复则讨论基础损耗和初步恢复。</p><p>本文实际对读维基文库《周易》各卦与《周易正义》卷三对应篇。引文为古籍文字，简体说明为本篇概括；用字有异处参考《正义》，例如噬嗑“臘肉”、剥“君子得輿”。《周易》单卦网页有时断句不同，剥卦辞按《正义》读为“不利有攸往”。这些整理不构成古本校勘结论，重要疑义另行标注。涉及日期、刑罚、王侯和祭祀时，应保留历史语境，不将其直接变成预测或今日行为规范。</p><h2 id="六十四卦详读三-随蛊临观至噬嗑贲剥复" tabindex="-1">六十四卦详读三：随蛊临观至噬嗑贲剥复 <a class="header-anchor" href="#六十四卦详读三-随蛊临观至噬嗑贲剥复" aria-label="Permalink to &quot;六十四卦详读三：随蛊临观至噬嗑贲剥复 {#六十四卦详读三-随蛊临观至噬嗑贲剥复}&quot;">​</a></h2><p>本组把注意力从个人进退转向关系如何形成、积弊如何修复、治理如何实施。随与蛊可比较顺从与整治，临与观可比较接近与审视，噬嗑与贲可比较强制裁断与文明表达，剥与复则讨论基础损耗和初步恢复。</p><p>本文实际对读维基文库《周易》各卦与《周易正义》卷三对应篇。引文为古籍文字，简体说明为本篇概括；用字有异处参考《正义》，例如噬嗑“臘肉”、剥“君子得輿”。《周易》单卦网页有时断句不同，剥卦辞按《正义》读为“不利有攸往”。这些整理不构成古本校勘结论，重要疑义另行标注。涉及日期、刑罚、王侯和祭祀时，应保留历史语境，不将其直接变成预测或今日行为规范。</p><h2 id="gua-17" tabindex="-1">17 随：跟随之前先辨其正 <a class="header-anchor" href="#gua-17" aria-label="Permalink to &quot;17 随：跟随之前先辨其正 {#gua-17}&quot;">​</a></h2><p><strong>卦符：䷐　上卦：兑 ☱（泽、悦）　下卦：震 ☳（雷、动）。</strong></p><p><strong>卦辞原文</strong>：隨：元亨，利貞，无咎。</p><p><strong>白话概括</strong>：动而悦，形成相随。但《正义》对这一卦特别加上条件：若以恶相随，便不能有四德、无咎；相随也可能成为朋党。因此随不是无条件服从，也不只是顺应流行。它同时讨论“我随谁”和“别人为什么随我”，领随两端都有责任。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：官有渝，貞吉。出門交有功。</td><td>职守、所主或原有关系有变化，守正则吉；走出原来的圈子交往，可以有所成。官的具体所指有异解。</td></tr><tr><td>六二：係小子，失丈夫。</td><td>系于一方就会失去另一方，关系选择不能无限兼得。小子、丈夫在古注中联系爻位，不宜机械按年龄择友。</td></tr><tr><td>六三：係丈夫，失小子。隨有求得，利居貞。</td><td>改变所随，可能有所获得，仍须守正。得到了想要的东西，不代表关系就完全合宜。</td></tr><tr><td>九四：隨有獲，貞凶。有孚在道，以明，何咎。</td><td>有人追随、有所收获也可能引起危险；须以诚信、合道而明白的方式自处。它专门限制“人多就是对”的想象。</td></tr><tr><td>九五：孚于嘉，吉。</td><td>信任、响应美善之事，才能使相随有正当方向。嘉不是任何取悦自己的声音。</td></tr><tr><td>上六：拘係之，乃從維之。王用亨于西山。</td><td>相随至深，出现系结与祭享西山之象。拘系、从维的断句和历史所指有异说，不能直接译成强迫他人服从。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“澤中有雷，隨；君子以嚮晦入宴息。”</p><p><strong>解释</strong>：将近黄昏便进入休息，取顺时而行之义。顺时也包括停止和恢复，不是永远追赶外界变化。宴息在这里是安息，不等同于纵乐。</p><p><strong>整体读法与误区</strong>：二、三两爻把选择的代价说得很直接；四、五两爻则把焦点转到拥有追随者的人。阅读时可问：追随的是情势、利益、个人，还是可说明的原则？所谓随时也不能成为取消承诺的借口。与<a href="/life/personal/yijing/hexagrams-17-24-part-01#gua-18">蛊卦</a>相邻，还可以看出顺应若没有反思，积久便可能需要整治。</p><p><strong>细读线索</strong>：六二与六三都用系字，却交换小子、丈夫的位置，强调选择关系的排他代价。九四随有获又把读者从求助者的位置移到受人追随者的位置：获可能同时增加负担和嫌疑。九五孚于嘉则进一步问，信任究竟投向什么。按这个次序阅读，可以从选择对象、承受代价、接受响应走到确认价值，随就不再只是一个把责任交给别人的被动动词。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9A%A8" target="_blank" rel="noopener noreferrer">《周易·随》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E9%9A%A8" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·随》</a>。</p><h2 id="gua-18" tabindex="-1">18 蛊：承接旧事，但不纵容旧弊 <a class="header-anchor" href="#gua-18" aria-label="Permalink to &quot;18 蛊：承接旧事，但不纵容旧弊 {#gua-18}&quot;">​</a></h2><p><strong>卦符：䷑　上卦：艮 ☶（山、止）　下卦：巽 ☴（风、入）。蛊读 gǔ。</strong></p><p><strong>卦辞原文</strong>：蠱：元亨，利涉大川。先甲三日，後甲三日。</p><p><strong>白话概括</strong>：蛊常从积弊、败坏读起，修复则意味着“有事”可为。《正义》着重以事解释蛊，把甲理解为创制之令：实行新令前后都须反复告知。它同时记载诸儒以辛、丁等干支解释三日，可见这不是只有一种解法的倒计时公式。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：幹父之蠱，有子，考无咎，厲終吉。</td><td>后人修理父辈遗留之事，使先人之失得到补救；仍有危险而可善终。考指父辈，不是现代考试。</td></tr><tr><td>九二：幹母之蠱，不可貞。</td><td>整治母辈旧事，不宜用过刚、固执的方式。古注从柔顺关系解释，不是主张放弃原则，更不说明女性天然应受宽纵。</td></tr><tr><td>九三：幹父之蠱，小有悔，无大咎。</td><td>整治较为刚急，会有小悔，但不至大咎。修复工作可能存在不完美，不应因此完全停手。</td></tr><tr><td>六四：裕父之蠱，往見吝。</td><td>对积弊一味宽缓纵容，继续下去将显出困窘。体谅来路不等于维持错误。</td></tr><tr><td>六五：幹父之蠱，用譽。</td><td>能以合宜德行承接、修理旧事，因而得到称誉。重点是修复方式，不能理解成替前人掩盖问题。</td></tr><tr><td>上九：不事王侯，高尚其事。</td><td>保留不进入王侯事务、另守其志的道路。不是每个人都必须在权力体系中证明自身价值。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“山下有風，蠱；君子以振民育德。”</p><p><strong>解释</strong>：面对积弊，需要振起民众、培育德性，既改变外在事务，也改变使问题反复发生的习惯。大象没有把解决方式缩成换一个人或发一次命令。</p><p><strong>整体读法与误区</strong>：父母之蛊将代际继承写得很具体：既有承接，也有修正，不是只有顺从。九二、九三、六四分别呈现方式太硬、略有过度与过分宽缓的差别；上九又留下自主选择。现代类比可以用于整理遗留问题，但应根据事实分清前人条件与当下责任，不能以“蛊”给家庭成员贴病理化标签。</p><p><strong>细读线索</strong>：五爻反复出现父母之蛊，表明旧事不是只靠一次斩断即可处理；它需要辨明承接方式。初六强调有子，六五强调用誉，中间穿插刚柔程度不同的整治。上九忽然离开父母与王事的重复语汇，给整齐的修复叙述留下另一条路：并非每个人都必须担任制度内的修补者。读这种转折，也是在学习经文怎样通过末爻改变读者对整卦的单一期待。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%A0%B1" target="_blank" rel="noopener noreferrer">《周易·蛊》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E8%A0%B1" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·蛊》</a>。</p><h2 id="gua-19" tabindex="-1">19 临：接近众人，也预见盛势的限度 <a class="header-anchor" href="#gua-19" aria-label="Permalink to &quot;19 临：接近众人，也预见盛势的限度 {#gua-19}&quot;">​</a></h2><p><strong>卦符：䷒　上卦：坤 ☷（地、顺）　下卦：兑 ☱（泽、悦）。</strong></p><p><strong>卦辞原文</strong>：臨：元亨，利貞。至于八月有凶。</p><p><strong>白话概括</strong>：阳自下渐长，有临近、监临、抚临之意；强盛趋势形成时，也要想到将来的退消。《正义》用卦气月建解释八月，历来起算与对应卦另有说法。因此“八月”首先是古代时间体系的问题，不是读到此卦就能断言公历八月发生灾事。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：咸臨，貞吉。</td><td>以感通或共同相临为开端，守正则吉。“咸”有感、皆等解释，不能只凭一个训诂排除全部读法。</td></tr><tr><td>九二：咸臨，吉无不利。</td><td>居中而能相应，临人的方式较为适当。《小象》又说未顺命，表明并非一味听命而行。</td></tr><tr><td>六三：甘臨，无攸利。既憂之，无咎。</td><td>用甜美姿态临人，却缺乏实质，无所利；若意识到问题并忧惧改正，可免咎。</td></tr><tr><td>六四：至臨，无咎。</td><td>真正临近合适对象或处于得当位置，没有过失。不能只停留在遥远的口头关怀。</td></tr><tr><td>六五：知臨，大君之宜，吉。</td><td>以智慧临人，知道如何任用和响应，不必亲自替所有人决定一切。知可联系智义。</td></tr><tr><td>上六：敦臨，吉无咎。</td><td>敦厚地临人，虽居外上仍以内部事务为念。厚道不是短暂表演，而是关系持续的态度。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“澤上有地，臨；君子以教思无窮，容保民无疆。”</p><p><strong>解释</strong>：地临于泽，取持续教养、容纳保护之义。教思无穷强调关怀与思考不能轻易中断；无疆是德性的表达，不等于现实资源没有边界。</p><p><strong>整体读法与误区</strong>：六爻多有积极判断，卦辞却先给出盛势不久的警告，这种张力应保留。临不是单向监控，六三甘临说明漂亮话也会失败，六五知临说明领导者需要判断与信任。现代可用它反思“是否真的接近实际处境”，但不能据此把自己放在天然高于他人的位置。</p><p><strong>细读线索</strong>：临的下方两阳在增长，卦辞因此容易给人纯粹乐观的感觉；但八月有凶把消长问题提前放入开头。六三甘临的位置与方式不合，说明增长期同样会产生失当做法。四、五、上的至、知、敦又展示不同的临人品质：真实到达、明智判断、厚道维持。它们不是必然递升的行政级别，而是让读者比较接近他人时究竟依靠甜言、位置还是实际作为。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E8%87%A8" target="_blank" rel="noopener noreferrer">《周易·临》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/03%E8%87%A8" target="_blank" rel="noopener noreferrer">《周易正义·上经随传卷三·临》</a>。</p>',37)])])}const f=r(o,[["render",s]]);export{c as __pageData,f as default};
